SELECT , s.supplier_name AS supplierName, p.product_code AS productCode, sk.spec_text AS specText FROM shop_supplier_product r LEFT JOIN shop_erp_supplier s ON s.id = r.supplier_id AND s.is_deleted = 0 LEFT JOIN shop_product_sku sk ON sk.id = r.sku_id AND sk.is_deleted = 0 LEFT JOIN shop_product p ON p.id = sk.product_id AND p.is_deleted = 0
r.is_deleted = 0
AND (r.product_name LIKE CONCAT('%', #{q.keyword}, '%') OR r.supply_code LIKE CONCAT('%', #{q.keyword}, '%') OR p.product_code LIKE CONCAT('%', #{q.keyword}, '%') OR sk.spec_text LIKE CONCAT('%', #{q.keyword}, '%') OR s.supplier_name LIKE CONCAT('%', #{q.keyword}, '%'))
AND r.supplier_id = #{q.supplierId}
AND r.supplier_id IN
#{sid}
AND r.category_id = #{q.categoryId}
AND r.status = #{q.status}
ORDER BY r.status DESC, r.id DESC

SELECT , p.product_code AS productCode, sk.spec_text AS specText FROM shop_supplier_product r INNER JOIN shop_product_sku sk ON sk.id = r.sku_id AND sk.is_deleted = 0 INNER JOIN shop_product p ON p.id = sk.product_id AND p.is_deleted = 0 WHERE r.is_deleted = 0 AND r.status = 1 AND r.supplier_id = #{supplierId}
AND (r.product_name LIKE CONCAT('%', #{keyword}, '%') OR p.product_code LIKE CONCAT('%', #{keyword}, '%') OR sk.spec_text LIKE CONCAT('%', #{keyword}, '%') OR r.supply_code LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY r.id DESC LIMIT #{limit}
